/*!
 * shaking-soon.js
 * 用法：
 *   1) 網頁放一個容器：<div id="shaking-soon"></div>
 *   2) 在容器後面引入這個 JS 檔（src="shaking-soon.js"）
 *   可在容器上加 data-width="500px" 設定寬度。
 *
 * 也可手動呼叫：ShakingSoon.mount('#my-box', { width: '600px' });
 */
(function (global) {
  var IMG = 'data:image/webp;base64,';

  function mount(target, opts) {
    opts = opts || {};
    var host = typeof target === 'string' ? document.querySelector(target) : target;
    if (!host) return null;
    var img = new Image();
    img.src = IMG;
    img.alt = opts.alt || 'Shaking Soon';
    img.style.display = 'block';
    img.style.width = opts.width || '100%';
    img.style.maxWidth = '100%';
    img.style.height = 'auto';
    img.style.margin = '0 auto';
    host.appendChild(img);
    return img;
  }

  global.ShakingSoon = { mount: mount, src: IMG };

  function auto() {
    var el = document.getElementById('shaking-soon');
    if (el) mount(el, { width: el.getAttribute('data-width') || undefined });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', auto);
  else auto();
})(window);
